import sys

def count_ones(x):
    return bin(x).count('1')

def solve(m, k):
    # We need to find the smallest n such that there are exactly m numbers
    # with exactly k ones in their binary representation among [n+1, 2*n]

    # Start with n = 1 and iterate upwards
    n = 1

    while True:
        count = 0
        # Check the range from n+1 to 2*n
        for num in range(n+1, 2*n+1):
            if count_ones(num) == k:
                count += 1
        # If we found exactly m numbers, return this n
        if count == m:
            return n
        n += 1

def main():
    input_data = sys.stdin.read().strip()
    m, k = map(int, input_data.split())

    result = solve(m, k)
    print(result)

if __name__ == "__main__":
    main()

